import type { AxiosRequestConfig } from 'axios';

export enum UserRequiredActionsEnum {
  UPDATE_EMAIL = 'update_email',
  UPDATE_PASSWORD = 'update_password',
}

export interface AuthClientOptions {
  clientId: string;
  identityUrl: string;
  redirectUri: string;
  logoutRedirectUri: string;
}

export interface RequiredActionsProps {
  email: boolean;
  password: boolean;
}

export interface FormUpdateFields {
  emailStr: string;
  passwordStr: string;
}

export interface AuthenticationContentValues {
  login(): Promise<void>;
  logout(): Promise<void>;
  loginRequest(username: string, password: string): Promise<void>;
  updateUserProperties: (email: string, password: string, photo?: File) => Promise<string>;
  tokenDecoded?: JwtDecodedPayload;
  isUnauthorized: boolean;
}

export interface IdentityServiceAuthenticationProviderProps {
  global: boolean;
  appName: string;
  options: AuthClientOptions;
}

export interface RetryableAxiosConfig extends AxiosRequestConfig {
  _retry?: boolean;
}

export type AuthBroadcastEvent = 'LOGIN' | 'LOGOUT' | 'SESSION_EXPIRED';

export interface JwtDecodedPayload {
  /**
   * User ID
   */
  sub: string;
  /**
   * Session ID
   */
  sid: string;
  jti: string;
  photo: string;
  firstname: string;
  lastname: string;
  email: string;
  iat: number;
  exp: number;
  aud: Array<string>;
  iss: string;
  [x: string]: any;
}
